KINDS
[
    #creature is a #thing
    #dragon is a #creature
    #wyrm is a #dragon
].

DEFINE
[
    @ember is a #wyrm
    @cinder is a #wyrm
    @north door is a #door
    @brass key is a #key
    @oak table is a #table
    @henry is a #guard
].

START
[
    @ember is calm
    @cinder is calm
    @north door is locked
    @brass key is on the #table
    @henry is calm
].

WHEN PLAYER takes @brass key
[
    |then (carry @brass key
].

IF @north door is locked
[
    |then (unlock @north door
].

WHEN PLAYER attacks @ember
[
    |then (damage @ember
    |then (change @ember to angry
].

WHEN PLAYER attacks a #creature
[
    |then (damage it
    |then (change it to angry
].

WHEN PLAYER attacks a #guard
[
    |then (damage it
    |then (change it to angry
].

IF @cinder is angry
[
    |then (damage PLAYER
].

KINDS
[
    #gate is a #door
].

DEFINE
[
    @north gate is a #gate
    @south gate is a #gate
    @brass bell is a #device
].

START
[
    @north gate has "North  Gate!" title
    @south gate has "South Gate." title
].

WHEN PLAYER sounds @brass bell
[
    |then (change title of every #gate to "OPEN — RubyVM!"
].

IF @north gate has "OPEN — RubyVM!" title
[
    |then (damage PLAYER
].

DEFINE
[
    @gold coin is a #thing
    @spikes is a #thing
    @bow is a #weapon
].

START
[
    PLAYER has 0 score
    PLAYER has 10 health
    @bow has 3 ammo
].

WHEN PLAYER takes @gold coin
[
    |then (increase score of PLAYER by 10
].

WHEN PLAYER attacks @spikes
[
    |then (decrease health of PLAYER by 3
].

WHEN PLAYER attacks @bow
[
    |then (decrease ammo of @bow by 1
].

IF PLAYER has at least 100 score
[
    |then (change PLAYER to friendly
].

IF PLAYER has more than 0 score
[
    |then (change PLAYER to alive
].

IF @bow has at most 0 ammo
[
    |then (change @bow to off
].

IF PLAYER has less than 1 health
[
    |then (change PLAYER to dead
].

DEFINE
[
    @boss is a #creature
    @bridge is a #thing
    @coin is a #thing
].

START
[
    PLAYER has 0 score
    PLAYER has 10 health
    PLAYER has 0 victories
    @boss is alive
    @bridge is whole
].

WHEN PLAYER takes @coin
[
    |then (increase score of PLAYER by 50
].

WHEN PLAYER attacks @boss
[
    |then (change @boss to dead
].

WHEN PLAYER speaks @boss
[
    |then (change @boss to alive
].

WHEN PLAYER attacks @bridge
[
    |then (change @bridge to broken
].

WHEN PLAYER speaks @bridge
[
    |then (change @bridge to whole
].

IF PLAYER has at least 100 score and @boss is dead
[
    |then (increase victories of PLAYER by 1
].

IF PLAYER has less than 1 health or @bridge is broken
[
    |then (change PLAYER to dead
].

DEFINE
[
    @lamp is a #thing
    @switch is a #thing
].

START
[
    @lamp is off
    PLAYER has 0 ifruns
    PLAYER has 0 otherwiseruns
].

WHEN PLAYER attacks @switch
[
    |then (change @lamp to on
].

WHEN PLAYER speaks @switch
[
    |then (change @lamp to off
].

IF @lamp is on
[
    |then (increase ifruns of PLAYER by 1
].
OTHERWISE
[
    |then (increase otherwiseruns of PLAYER by 1
].
